function renderPaymentDetail(id) {
  var c = $('#content');
  var load = PAY_CACHE.length ? Promise.resolve(PAY_CACHE) : api('api_admin_listPayments', session.token, {}).then(function (r) { return r.items; });
  c.innerHTML = '<div class="card"><div class="skeleton" style="height:240px"></div></div>';
  Promise.all([load, loadSource('payment_methods')]).then(function (r) {
    PAY_CACHE = r[0];
    var p = PAY_CACHE.filter(function (x) { return x.id === id; })[0];
    if (!p) throw new Error('NOT_FOUND: Not found.');
    var m = SOURCES.payment_methods.filter(function (x) { return x.id === p.method_id; })[0];
    var editable = canWrite('payments');
    var outstanding = Math.max(0, Number(p.amount_due || 0) - Number(p.amount_received || 0));
    var closed = p.status === 'CANCELLED' || p.status === 'REFUNDED' || outstanding <= 0;
    var statusChoices = Number(p.amount_received || 0) > 0 ? ['REFUND_REQUESTED'] : PAY_SETTABLE;
    c.innerHTML =
      '<div class="toolbar"><a class="btn btn-sm btn-ghost" href="#/payments">' + icon('arrow', 'back-arrow') + esc(t('ui.back')) + '</a></div>' +
      '<div class="grid detail-grid"><div class="card stack"><div class="row" style="justify-content:space-between"><h2 style="margin:0" dir="ltr">' + esc(p.payment_ref) + '</h2>' + badgeA(p.status, PAY_TONE_A) + '</div>' +
        '<dl class="dl">' + dlRow('f.reference', p.request_reference) + dlRow('f.name', p.visitor_name) + dlRow('f.phone', p.visitor_phone) +
          dlRow('f.method', m ? tf(m, 'name') : p.method_id) + dlRow('f.amountDue', formatMoney(Number(p.amount_due || 0), p.currency)) +
          dlRow('f.received', formatMoney(Number(p.amount_received || 0), p.currency)) + dlRow('f.paymentDate', p.payment_date) + dlRow('f.receiptRef', p.receipt_ref) +
          dlRow('ops.confirmedBy', p.confirmed_by_email) + dlRow('ops.refunded', p.refund_amount ? formatMoney(Number(p.refund_amount), p.currency) + ' · ' + p.refund_date + ' · ' + p.refund_reason : '') +
          dlRow('ops.deadline', String(p.deadline_at || '').slice(0, 10)) + '</dl>' +
        (p.notes ? '<div class="well"><p dir="auto" style="white-space:pre-wrap;margin:0">' + esc(p.notes) + '</p></div>' : '') + '</div>' +
      '<div class="stack-lg">' +
        (editable && !closed ? '<form class="card stack" id="pay-rec" novalidate><h3>' + icon('cash') + esc(t('ops.recordReceipt')) + '</h3>' +
          '<p class="small muted">' + esc(t('ops.recordHint')) + '</p>' +
          '<div class="field"><label for="pr-amount">' + esc(t('f.amount')) + '</label><input class="input" id="pr-amount" type="number" step="0.01" min="0.01" required dir="ltr" value="' + (outstanding || '') + '"></div>' +
          '<div class="field"><label for="pr-date">' + esc(t('f.paymentDate')) + '</label><input class="input" id="pr-date" type="date" required value="' + today() + '"></div>' +
          '<div class="field"><label for="pr-ref">' + esc(t('f.receiptRef')) + '</label><input class="input" id="pr-ref" required maxlength="80" dir="ltr"></div>' +
          '<div class="field"><label for="pr-notes">' + esc(t('f.notes')) + '</label><textarea class="textarea" id="pr-notes" rows="2"></textarea></div>' +
          '<div class="err" id="pr-err"></div><button class="btn btn-primary" type="submit">' + esc(t('ops.confirmReceipt')) + '</button></form>' : '') +
        (editable && Number(p.amount_received) > Number(p.refund_amount || 0) ? '<form class="card stack" id="pay-ref" novalidate><h3>' + esc(t('ops.recordRefund')) + '</h3>' +
          '<div class="field"><label for="rf-amount">' + esc(t('f.amount')) + '</label><input class="input" id="rf-amount" type="number" step="0.01" min="0.01" required dir="ltr"></div>' +
          '<div class="field"><label for="rf-date">' + esc(t('f.paymentDate')) + '</label><input class="input" id="rf-date" type="date" required value="' + today() + '"></div>' +
          '<div class="field"><label for="rf-reason">' + esc(t('f.reason')) + '</label><textarea class="textarea" id="rf-reason" rows="2" required></textarea></div>' +
          '<div class="err" id="rf-err"></div><button class="btn" type="submit">' + esc(t('ops.recordRefund')) + '</button></form>' : '') +
        (editable ? '<form class="card stack" id="pay-st" novalidate><h3>' + esc(t('ops.changeStatus')) + '</h3><p class="small muted">' + esc(t('ops.statusHint')) + '</p>' +
          selectHtml('ps-status', statusChoices, '', t('ops.chooseStatus')) +
          '<input class="input" id="ps-note" maxlength="500" placeholder="' + esc(t('f.notes')) + '">' +
          '<div class="err" id="ps-err"></div><button class="btn btn-sm" type="submit">' + esc(t('common.save')) + '</button></form>' : '') +
      '</div></div>';
    function after(promise, errId) {
      promise.then(function () { toast(t('ui.saved'), 'success'); PAY_CACHE = []; REQ_CACHE = []; renderPaymentDetail(id); })
        .catch(function (err) { $(errId).textContent = apiMsg(err); });
    }
    if ($('#pay-rec')) $('#pay-rec').addEventListener('submit', function (e) {
      e.preventDefault(); if (!e.target.checkValidity()) { e.target.reportValidity(); return; }
      confirmDialog(t('ops.confirmReceipt'), tvA('ops.confirmReceiptText', { amount: formatMoney(Number($('#pr-amount').value), p.currency), ref: $('#pr-ref').value }), t('common.confirm')).then(function (ok) {
        if (ok) after(api('api_admin_recordPayment', session.token, id, { amount: $('#pr-amount').value, payment_date: $('#pr-date').value, receipt_ref: $('#pr-ref').value, notes: $('#pr-notes').value }), '#pr-err');
      });
    });
    if ($('#pay-ref')) $('#pay-ref').addEventListener('submit', function (e) {
      e.preventDefault(); if (!e.target.checkValidity()) { e.target.reportValidity(); return; }
      confirmDialog(t('ops.recordRefund'), formatMoney(Number($('#rf-amount').value), p.currency), t('common.confirm')).then(function (ok) {
        if (ok) after(api('api_admin_refundPayment', session.token, id, { amount: $('#rf-amount').value, refund_date: $('#rf-date').value, reason: $('#rf-reason').value }), '#rf-err');
      });
    });
    if ($('#pay-st')) $('#pay-st').addEventListener('submit', function (e) {
      e.preventDefault();
      if (!$('#ps-status').value) { $('#ps-err').textContent = t('ops.chooseStatus'); return; }
      confirmDialog(t('ops.changeStatus'), $('#ps-status').value, t('common.confirm')).then(function (ok) {
        if (ok) after(api('api_admin_setPaymentStatus', session.token, id, $('#ps-status').value, $('#ps-note').value), '#ps-err');
      });
    });
  }).catch(handleApiError);
}

/* ---- Reports ---------------------------------------------------------------------------- */
function renderReports() {
  var c = $('#content');
  var now = new Date(), first = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().slice(0, 10);
  c.innerHTML = '<div class="notice small" style="margin-block-end:var(--s4)">' + icon('info') + '<span>' + esc(t('ops.reportIntro')) + '</span></div>' +
    '<form class="toolbar" id="rp-form"><label class="row small">' + esc(t('ops.from')) + ' <input class="input" type="date" id="rp-from" value="' + first + '"></label>' +
    '<label class="row small">' + esc(t('ops.to')) + ' <input class="input" type="date" id="rp-to" value="' + today() + '"></label>' +
    '<button class="btn btn-sm btn-primary" type="submit">' + esc(t('ops.show')) + '</button></form><div id="rp-out"></div>';
  function load() {
    $('#rp-out').innerHTML = '<div class="grid kpis">' + skeletonCards(6, 70) + '</div>';
    Promise.all([loadSource('categories'), api('api_admin_paymentReport', session.token, $('#rp-from').value, $('#rp-to').value)]).then(function (r) {
      var rp = r[1], cats = {};
      SOURCES.categories.forEach(function (x) { cats[x.id] = tf(x, 'title'); });
      var table = function (title, obj, labelFn) {
        var keys = Object.keys(obj).sort();
        return '<div class="card"><h3>' + esc(title) + '</h3>' + (keys.length ? '<table class="table"><tbody>' + keys.map(function (k) {
          return '<tr><td>' + esc(labelFn ? labelFn(k) : k) + '</td><td style="text-align:end">' + esc(formatMoney(obj[k], 'EUR')) + '</td></tr>';
        }).join('') + '</tbody></table>' : '<p class="muted small">' + esc(t('ui.empty')) + '</p>') + '</div>';
      };
      $('#rp-out').innerHTML = '<div class="grid kpis">' +
        kpi('ops.received', formatMoney(rp.received, 'EUR'), 'cash') + kpi('ops.cash', formatMoney(rp.cash, 'EUR'), 'cash') +
        kpi('ops.card', formatMoney(rp.card, 'EUR'), 'file') + kpi('ops.online', formatMoney(rp.online, 'EUR'), 'globe') +
        kpi('ops.pending', formatMoney(rp.pending, 'EUR'), 'bell') + kpi('ops.refunded', formatMoney(rp.refunded, 'EUR'), 'arrow') + '</div>' +
        '<div class="grid report-grid">' + table(t('ops.byDay'), rp.byDay) + table(t('ops.byMonth'), rp.byMonth) +
        table(t('ops.byCategory'), rp.byCategory, function (k) { return cats[k] || k; }) + '</div>';
    }).catch(handleApiError);
  }
  $('#rp-form').addEventListener('submit', function (e) { e.preventDefault(); load(); });
  load();
}

